static void pages_work_handler ( struct work_struct * work ) { struct mlx5_pages_req * req = container_of ( work , mlx5_pages_req , work ) ; struct mlx5_core_dev * dev = req -> dev ; int err = 0 ; if ( req -> release_all ) { release_all_pages ( dev , req -> func_id , req -> ec_function ) ; } if ( req -> npages < 0 ) { err = reclaim_pages ( dev , req -> func_id , - 1 * req -> npages , NULL , true , req -> ec_function ) ; } if ( req -> npages > 0 ) { err = give_pages ( dev , req -> func_id , req -> npages , 1 , req -> ec_function ) ; } if ( err ) { mlx5_core_warn ( dev , "%s fail %d\n" , req -> npages < 0 ?"reclaim" : "give" , err ) ; } } 